#!/usr/bin/env python3
import sys
from pathlib import Path

if len(sys.argv) != 2:
    raise SystemExit('usage: stage-a6-rg35xx-raw-polygon-r5p.py <repo-root>')
root = Path(sys.argv[1]).resolve()
pg = root / 'build/a3/stage-src/org/recompile/mobile/PlatformGraphics.java'
pt = pg.read_text(encoding='utf-8')

old = '''\tpublic void setAlphaRGB(int ARGB)\n\t{\n\t\tgc.setColor(new Color(ARGB, true));\n\t}\n'''
new = '''\tpublic void setAlphaRGB(int ARGB)\n\t{\n\t\tif(platformImage != null && platformImage.isRG35XXRaw())\n\t\t{\n\t\t\tcolorAlpha = (ARGB >>> 24) & 0xFF;\n\t\t\tcolor = ARGB & 0x00FFFFFF;\n\t\t\treturn;\n\t\t}\n\t\tgc.setColor(new Color(ARGB, true));\n\t}\n'''
if pt.count(old) != 1:
    raise SystemExit('A6_R5P_STAGE_FAIL setAlphaRGB anchor count=%d' % pt.count(old))
pt = pt.replace(old, new, 1)

old = '''\tpublic void fillPolygon(int[] xPoints, int xOffset, int[] yPoints, int yOffset, int nPoints, int argbColor)\n\t{\n\t\tint temp = color;\n\t\tint[] x = new int[nPoints];\n\t\tint[] y = new int[nPoints];\n\n\t\tsetAlphaRGB(argbColor);\n\n\t\tfor(int i=0; i<nPoints; i++)\n\t\t{\n\t\t\tx[i] = xPoints[xOffset+i];\n\t\t\ty[i] = yPoints[yOffset+i];\n\t\t}\n\t\tgc.fillPolygon(x, y, nPoints);\n\t\tsetColor(temp);\n\t}\n'''
new = '''\tprivate int rg35xxSourceOver(int s, int d)\n\t{\n\t\tint sa = (s >>> 24) & 0xFF;\n\t\tif(sa == 0) return d;\n\t\tif(sa == 255) return s;\n\t\tint da = (d >>> 24) & 0xFF;\n\t\tint inv = 255 - sa;\n\t\tint outA255 = sa * 255 + da * inv;\n\t\tif(outA255 == 0) return 0;\n\t\tint oa = (outA255 + 127) / 255;\n\t\tint sr = (s >>> 16) & 0xFF, sg = (s >>> 8) & 0xFF, sb = s & 0xFF;\n\t\tint dr = (d >>> 16) & 0xFF, dg = (d >>> 8) & 0xFF, db = d & 0xFF;\n\t\tint r = (sr * sa * 255 + dr * da * inv + outA255 / 2) / outA255;\n\t\tint g = (sg * sa * 255 + dg * da * inv + outA255 / 2) / outA255;\n\t\tint b = (sb * sa * 255 + db * da * inv + outA255 / 2) / outA255;\n\t\treturn (oa << 24) | (r << 16) | (g << 8) | b;\n\t}\n\n\tprivate void rg35xxFillSpan(int[] pixels, int pw, int y, int left, int right, int argb)\n\t{\n\t\tif(right <= left) return;\n\t\tint di = y * pw + left;\n\t\tint a = (argb >>> 24) & 0xFF;\n\t\tif(a == 255)\n\t\t{\n\t\t\tfor(int x=left; x<right; x++, di++) pixels[di] = argb;\n\t\t}\n\t\telse if(a != 0)\n\t\t{\n\t\t\tfor(int x=left; x<right; x++, di++) pixels[di] = rg35xxSourceOver(argb, pixels[di]);\n\t\t}\n\t}\n\n\tprivate void rg35xxFillPolygon(int[] xPoints, int xOffset, int[] yPoints, int yOffset, int nPoints, int argbColor)\n\t{\n\t\tif(nPoints < 3 || xPoints == null || yPoints == null) return;\n\t\tif(xOffset < 0 || yOffset < 0 || xOffset + nPoints > xPoints.length || yOffset + nPoints > yPoints.length) return;\n\t\tint[] pixels = platformImage.getRG35XXPixels();\n\t\tint pw = platformImage.getRG35XXWidth();\n\t\tint ph = platformImage.getRG35XXHeight();\n\t\tint clipL = clipX < 0 ? 0 : clipX;\n\t\tint clipT = clipY < 0 ? 0 : clipY;\n\t\tint clipR = clipX + clipWidth;\n\t\tint clipB = clipY + clipHeight;\n\t\tif(clipR > pw) clipR = pw;\n\t\tif(clipB > ph) clipB = ph;\n\t\tif(clipR <= clipL || clipB <= clipT) return;\n\n\t\tint[] xs = new int[nPoints];\n\t\tint[] ys = new int[nPoints];\n\t\tint minX = 2147483647, maxX = -2147483648;\n\t\tint minY = 2147483647, maxY = -2147483648;\n\t\tfor(int i=0; i<nPoints; i++)\n\t\t{\n\t\t\tint x = xPoints[xOffset+i] + translateX;\n\t\t\tint y = yPoints[yOffset+i] + translateY;\n\t\t\txs[i] = x; ys[i] = y;\n\t\t\tif(x < minX) minX = x; if(x > maxX) maxX = x;\n\t\t\tif(y < minY) minY = y; if(y > maxY) maxY = y;\n\t\t}\n\n\t\t// Locked Vua Cuop Bien uses four-corner axis-aligned DirectGraphics polygons.\n\t\t// Keep this generic but give that hot path an allocation-free span loop.\n\t\tif(nPoints == 4 && minX < maxX && minY < maxY)\n\t\t{\n\t\t\tint mask = 0; boolean rect = true;\n\t\t\tfor(int i=0; i<4; i++)\n\t\t\t{\n\t\t\t\tint bit;\n\t\t\t\tif(xs[i] == minX && ys[i] == minY) bit = 1;\n\t\t\t\telse if(xs[i] == maxX && ys[i] == minY) bit = 2;\n\t\t\t\telse if(xs[i] == maxX && ys[i] == maxY) bit = 4;\n\t\t\t\telse if(xs[i] == minX && ys[i] == maxY) bit = 8;\n\t\t\t\telse { rect = false; break; }\n\t\t\t\tmask |= bit;\n\t\t\t}\n\t\t\tif(rect && mask == 15)\n\t\t\t{\n\t\t\t\tint left = minX < clipL ? clipL : minX;\n\t\t\t\tint right = maxX > clipR ? clipR : maxX;\n\t\t\t\tint top = minY < clipT ? clipT : minY;\n\t\t\t\tint bottom = maxY > clipB ? clipB : maxY;\n\t\t\t\tfor(int y=top; y<bottom; y++) rg35xxFillSpan(pixels, pw, y, left, right, argbColor);\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\n\t\t// Generic even-odd scanline fallback for simple polygons.\n\t\tint top = minY < clipT ? clipT : minY;\n\t\tint bottom = maxY > clipB ? clipB : maxY;\n\t\tif(bottom <= top) return;\n\t\tint[] intersections = new int[nPoints];\n\t\tfor(int y=top; y<bottom; y++)\n\t\t{\n\t\t\tint count = 0;\n\t\t\tfor(int i=0, j=nPoints-1; i<nPoints; j=i++)\n\t\t\t{\n\t\t\t\tint y1 = ys[j], y2 = ys[i];\n\t\t\t\tif((y1 <= y && y2 > y) || (y2 <= y && y1 > y))\n\t\t\t\t{\n\t\t\t\t\tlong num = (long)(y - y1) * (long)(xs[i] - xs[j]);\n\t\t\t\t\tint x = xs[j] + (int)(num / (long)(y2 - y1));\n\t\t\t\t\tintersections[count++] = x;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor(int i=1; i<count; i++)\n\t\t\t{\n\t\t\t\tint v = intersections[i], k = i-1;\n\t\t\t\twhile(k >= 0 && intersections[k] > v) { intersections[k+1] = intersections[k]; k--; }\n\t\t\t\tintersections[k+1] = v;\n\t\t\t}\n\t\t\tfor(int i=0; i+1<count; i+=2)\n\t\t\t{\n\t\t\t\tint left = intersections[i] < clipL ? clipL : intersections[i];\n\t\t\t\tint right = intersections[i+1] > clipR ? clipR : intersections[i+1];\n\t\t\t\trg35xxFillSpan(pixels, pw, y, left, right, argbColor);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic void fillPolygon(int[] xPoints, int xOffset, int[] yPoints, int yOffset, int nPoints, int argbColor)\n\t{\n\t\tif(platformImage != null && platformImage.isRG35XXRaw())\n\t\t{\n\t\t\trg35xxFillPolygon(xPoints, xOffset, yPoints, yOffset, nPoints, argbColor);\n\t\t\treturn;\n\t\t}\n\t\tint temp = color;\n\t\tint[] x = new int[nPoints];\n\t\tint[] y = new int[nPoints];\n\n\t\tsetAlphaRGB(argbColor);\n\n\t\tfor(int i=0; i<nPoints; i++)\n\t\t{\n\t\t\tx[i] = xPoints[xOffset+i];\n\t\t\ty[i] = yPoints[yOffset+i];\n\t\t}\n\t\tgc.fillPolygon(x, y, nPoints);\n\t\tsetColor(temp);\n\t}\n'''
if pt.count(old) != 1:
    raise SystemExit('A6_R5P_STAGE_FAIL fillPolygon anchor count=%d' % pt.count(old))
pt = pt.replace(old, new, 1)
pg.write_text(pt, encoding='utf-8')

print('A6_R5P_RAW_POLYGON_STAGE=PASS')
print('A6_R5P_OWNER=RAW2D_DIRECTGRAPHICS_FILLPOLYGON_AWT_NULL')
print('A6_R5P_SETALPHARGB_RAW_SAFE=YES')
print('A6_R5P_FILLPOLYGON_RAW=RECT_FASTPATH+GENERIC_SCANLINE+SOURCE_OVER')
